#!/usr/bin/env bash
# gateway-deploy.sh <source commit> <image:tag> <image digest> <chart version>
#
# Makes the one Halo gateway deployment ref. The homelab reads the chart from git at deploy/current, so that ref points
# at a synthetic commit whose parent is the released source commit and whose deployed-image.yaml pins the image by
# digest. Moving one ref therefore changes the chart and image together.
#
# Re-runs reuse an identical deploy. An older run never moves deploy/current behind (or sideways from) the source commit
# it already deploys. Env: GH_TOKEN (contents: write), GITHUB_REPOSITORY, and optionally RUN_URL.
set -euo pipefail

values() {
  local image=${1:?} digest=${2:?} version=${3:?}
  local repository=${image%:*} tag=${image##*:}
  [[ "$repository" != "$image" && -n "$tag" ]] || {
    echo "::error::Expected an image with a tag, got $image" >&2
    exit 1
  }
  [[ "$digest" =~ ^sha256:[0-9a-f]{64}$ ]] || {
    echo "::error::Expected a sha256 image digest, got $digest" >&2
    exit 1
  }
  printf '%s\n' \
    '# Generated by gateway-deploy.sh. deploy/current keeps this file and the chart in one commit.' \
    "# halo-gateway $version" \
    'image:' \
    "  repository: $repository" \
    "  tag: \"$tag\"" \
    "  digest: \"$digest\""
}

if [[ "${1:-}" = --values ]]; then
  values "${2:?}" "${3:?}" "${4:?}"
  exit
fi

source_commit=${1:?usage: $0 <source commit> <image:tag> <image digest> <chart version>}
image=${2:?} digest=${3:?} version=${4:?}
repo=${GITHUB_REPOSITORY:?}
tag=deploy/current
ref=refs/tags/$tag
path=charts/halo-gateway/deployed-image.yaml
content=$(values "$image" "$digest" "$version")$'\n'

current=$(gh api "repos/$repo/git/ref/tags/$tag" --jq .object.sha 2>/dev/null || true)
deploy=
if [[ -n "$current" ]]; then
  deployed=$(gh api "repos/$repo/contents/$path?ref=$current" --jq .content 2>/dev/null | base64 -d || true)
  deployed+=$'\n'
  if [[ "$deployed" = "$content" ]]; then
    echo "$tag ($current) already deploys halo-gateway $version: reusing it."
    deploy=$current
  else
    on=$(gh api "repos/$repo/git/commits/$current" --jq '.parents[0].sha')
    if [[ "$on" = "$source_commit" ]]; then
      status=identical
    else
      status=$(gh api "repos/$repo/compare/$on...$source_commit" --jq .status)
    fi
    if [[ "$status" != ahead && "$status" != identical ]]; then
      echo "::notice::$tag stays on ${on:0:7}; this run's ${source_commit:0:7} is $status of it"
      echo "- \`$tag\` stays on \`${on:0:7}\` (\`${source_commit:0:7}\` is $status of it)" >> "${GITHUB_STEP_SUMMARY:-/dev/null}"
      exit 0
    fi
  fi
fi

if [[ -z "$deploy" ]]; then
  work=$(mktemp -d)
  trap 'rm -rf "$work"' EXIT
  base_tree=$(gh api "repos/$repo/git/commits/$source_commit" --jq .tree.sha)
  jq -cn --arg base "$base_tree" --arg path "$path" --arg content "$content" \
    '{base_tree: $base, tree: [{path: $path, mode: "100644", type: "blob", content: $content}]}' > "$work/tree.json"
  tree=$(gh api "repos/$repo/git/trees" -X POST --input "$work/tree.json" --jq .sha)
  message="Deploy halo-gateway $version: $source_commit with $image@$digest"
  [[ -z "${RUN_URL:-}" ]] || message+=$'\n\n'"Run: $RUN_URL"
  jq -cn --arg tree "$tree" --arg parent "$source_commit" --arg message "$message" \
    '{message: $message, tree: $tree, parents: [$parent]}' > "$work/commit.json"
  deploy=$(gh api "repos/$repo/git/commits" -X POST --input "$work/commit.json" --jq .sha)
fi

if [[ "$deploy" != "$current" ]]; then
  if [[ -n "$current" ]]; then
    gh api "repos/$repo/git/refs/tags/$tag" -X PATCH -f sha="$deploy" -F force=true --jq .object.sha > /dev/null
  else
    gh api "repos/$repo/git/refs" -X POST -f ref="$ref" -f sha="$deploy" --jq .object.sha > /dev/null
  fi
fi

echo "Deployed halo-gateway $version: $tag -> $deploy (chart at $source_commit, image $image@$digest)"
echo "deploy_commit=$deploy" >> "${GITHUB_OUTPUT:-/dev/null}"
echo "- deployed \`$tag\` at [\`${deploy:0:7}\`](https://github.com/$repo/commit/$deploy)" >> "${GITHUB_STEP_SUMMARY:-/dev/null}"
